// NetOps Authentic Bell Sound Engine
// Embedded base64 audio guarantees zero-latency, offline-capable playback across all browsers.

const BELL_RING_DATA_URI = 'data:audio/mp3;base64,';
const DESK_BELL_DATA_URI = 'data:audio/mp3;base64,';

/**
 * Play authentic physical metallic bell sound (acoustic recording).
 */
export const playBellSound = (type = 'ring') => {
  try {
    const dataUri = type === 'desk' ? DESK_BELL_DATA_URI : BELL_RING_DATA_URI;
    const audio = new Audio(dataUri);
    audio.volume = 0.95;
    const promise = audio.play();
    if (promise !== undefined) {
      promise.catch((err) => {
        try {
          const fallback = new Audio(type === 'desk' ? '/desk_bell.mp3' : '/bell.mp3');
          fallback.volume = 0.95;
          fallback.play().catch(() => {});
        } catch (_) {}
      });
    }
  } catch (e) {
    console.warn('Bell audio playback encountered an issue:', e);
  }
};

export default playBellSound;
